        if com.needs_i8_conversion(self):
            boxer = com.i8_boxer(self)

            if len(values) == 0:
                return boxer(tslib.iNaT)

            values = values.view('i8')
            result = func(values)

            if com.is_list_like(result):
                result = result.map(boxer)
            else:
                result = boxer(result)

        else:

            # let the function return nan if appropriate
            if dropna:
                if len(values) == 0:
                    return np.nan
            result = func(values)

        return result

